package com.travbook.railtickets.domain.model;
import com.travbook.rail.domain.model.Rail.*;
import com.travbook.shared.domain.DomainFailure;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import static com.travbook.shared.domain.DomainFailure.Code.*;
public final class RailTicket {
 private RailTicket(){}
 public enum Scenario {SUCCESS,AUTH_DECLINED,RESERVATION_REJECTED,CAPTURE_DECLINED,RESERVATION_RESPONSE_LOST,CAPTURE_RESPONSE_LOST}
 public enum Status {PROCESSING,ISSUED,FAILED,CANCELLATION_PENDING,CANCELLED,REVIEW}
 public enum Payment {NOT_STARTED,AUTHORIZED,CAPTURED,DECLINED,VOIDED}
 public enum Reservation {NOT_STARTED,CONFIRMED,RAC,WAITLIST,REJECTED,CANCELLED}
 public enum Refund {NONE,PENDING,SUCCEEDED,NOT_DUE}
 public enum Step {VALIDATE,AUTHORIZE,RESERVE,CAPTURE,CANCEL,VOID,REFUND,REFUND_STATUS,DONE,REVIEW}
 public enum Berth {NONE,LOWER,MIDDLE,UPPER}
 public static final String PARTIAL_POLICY="MOCK-RAIL-PARTIAL-V1";
 public static final String POLICY="MOCK-RAIL-V1";
 public static final String CANCELLATION="Synthetic MOCK-RAIL-V1: cancel all passengers before departure; base fare refunded, simulated charges retained. Not an official railway policy.";
 public record Passenger(String givenName,String familyName,LocalDate dateOfBirth,Berth berthPreference){
  public Passenger{givenName=name(givenName);familyName=name(familyName);if(dateOfBirth==null||berthPreference==null)throw new DomainFailure(VALIDATION_FAILED,"Passenger birth date and berth preference are required.");}
  private static String name(String s){if(s==null)throw new DomainFailure(VALIDATION_FAILED,"Passenger name required.");s=java.text.Normalizer.normalize(s,java.text.Normalizer.Form.NFC).replaceAll("[\\s\\p{Zs}]+"," ").strip();if(s.codePoints().noneMatch(Character::isLetter)||!s.matches("[\\p{L}\\p{M} .’'-]{1,60}"))throw new DomainFailure(VALIDATION_FAILED,"Use valid passenger names up to 60 characters.");return s;}
 }
 public static void eligible(Journey journey,TravelClass travelClass,Quota quota,String boarding,List<Passenger> passengers){
  if(!journey.origin().code().equals(boarding))throw new DomainFailure(VALIDATION_FAILED,"This MOCK route supports boarding at the origin only.");
  if(passengers==null||passengers.isEmpty()||passengers.size()>(quota==Quota.TATKAL?4:6)||passengers.stream().anyMatch(Objects::isNull))throw new DomainFailure(VALIDATION_FAILED,"MOCK policy allows 1–6 passengers; synthetic Tatkal allows at most four.");
  var seen=new HashSet<String>();boolean adult=false;for(var p:passengers){int age=Period.between(p.dateOfBirth(),journey.departure().toLocalDate()).getYears();if(age<5||age>120||p.dateOfBirth().isAfter(journey.departure().toLocalDate()))throw new DomainFailure(VALIDATION_FAILED,"MOCK policy supports ages 5–120 at departure; under-five and concession fares are not supported.");adult|=age>=18;if(!seen.add((p.givenName()+":"+p.familyName()+":"+p.dateOfBirth()).toLowerCase(Locale.ROOT)))throw new DomainFailure(VALIDATION_FAILED,"Each passenger must appear once.");if(travelClass==TravelClass.TWO_AC&&p.berthPreference()==Berth.MIDDLE)throw new DomainFailure(VALIDATION_FAILED,"Middle berth preference is not supported for 2AC.");}if(!adult)throw new DomainFailure(VALIDATION_FAILED,"MOCK policy requires an accompanying adult aged 18 or older.");
 }
 public record Selection(Journey journey,Availability availability,String boardingStation,List<Passenger> passengers,Money previousTotal,Money total,Instant checkedAt,Instant expiresAt,String policy){
  public Selection{passengers=List.copyOf(passengers);eligible(journey,availability.travelClass(),availability.quota(),boardingStation,passengers);if(!POLICY.equals(policy)||availability.status()==com.travbook.rail.domain.model.Rail.Status.UNAVAILABLE||availability.status()==com.travbook.rail.domain.model.Rail.Status.NOT_OPEN)throw new DomainFailure(OFFER_UNAVAILABLE,"This class/quota cannot be reserved.");if(total.amount().compareTo(availability.total().amount().multiply(BigDecimal.valueOf(passengers.size())))!=0)throw new IllegalArgumentException("Passenger fare mismatch");}
 }
 public record Quote(UUID id,UUID owner,int version,Selection selection,Instant createdAt,Instant expiresAt){
  public Quote{if(id==null||owner==null||version!=1||!expiresAt.isAfter(createdAt)||expiresAt.isAfter(selection.expiresAt()))throw new IllegalArgumentException("Invalid rail quote");}
  public Instant departure(){return selection.journey().departure().toInstant();}
  public Instant effectiveExpiry(){return expiresAt.isBefore(departure())?expiresAt:departure();}
  public boolean expired(Instant now){return !effectiveExpiry().isAfter(now);}
  public void valid(Instant now){if(expired(now))throw new DomainFailure(QUOTE_EXPIRED,"This rail quote expired. Request and accept a fresh quote.");}
 }
 public record CancellationQuote(UUID id,UUID bookingId,UUID owner,long bookingVersion,Money refundAmount,Money retainedAmount,Instant createdAt,Instant expiresAt,List<Integer> passengerIndexes){public CancellationQuote{if(passengerIndexes!=null)passengerIndexes=List.copyOf(passengerIndexes);}public String policy(){return passengerIndexes==null?POLICY:PARTIAL_POLICY;}}
 public record Cancellation(CancellationQuote quote,boolean simulateDelay,boolean simulateResponseLoss,UUID commandId){}
 public record Booking(UUID id,Quote quote,Instant acceptedAt,Scenario scenario,UUID commandId,UUID correlationId,
                       long version,Instant createdAt,Instant updatedAt,Status status,Payment payment,Reservation reservation,Refund refund,Step step,
                       String supplierReference,String paymentReference,String refundReference,String failureCode,Cancellation cancellation,List<Integer> cancelledPassengerIndexes){
  public Booking{cancelledPassengerIndexes=cancelledPassengerIndexes==null?(reservation==Reservation.CANCELLED&&cancellation!=null?java.util.stream.IntStream.range(0,quote.selection().passengers().size()).boxed().toList():List.of()):List.copyOf(cancelledPassengerIndexes);if(status==Status.ISSUED&&(payment!=Payment.CAPTURED||!issuedReservation(reservation))||status==Status.CANCELLED&&reservation!=Reservation.CANCELLED)throw new IllegalArgumentException("Invalid independent rail states");}
  public static Booking create(UUID id,Quote q,Instant accepted,Scenario scenario,UUID command,UUID correlation,Instant now){q.valid(now);return new Booking(id,q,accepted,scenario,command,correlation,1,now,now,Status.PROCESSING,Payment.NOT_STARTED,Reservation.NOT_STARTED,Refund.NONE,Step.VALIDATE,null,null,null,null,null,List.of());}
  public UUID operation(Step operation){UUID scope=passengerChanges()&&(operation==Step.CANCEL||operation==Step.REFUND)?cancellation.quote().id():id;return UUID.nameUUIDFromBytes((scope+":"+operation.name()).getBytes(StandardCharsets.UTF_8));}
  public boolean terminal(){return step==Step.DONE||step==Step.REVIEW;}
  private void require(Step expected){if(step!=expected)throw new DomainFailure(BOOKING_CONFLICT,"Rail workflow step mismatch.");}
  private Booking next(Status s,Payment p,Reservation r,Refund f,Step next,String supplier,String pay,String ref,String failure,Cancellation cancel,Instant now){return new Booking(id,quote,acceptedAt,scenario,commandId,correlationId,version+1,createdAt,now,s,p,r,f,next,supplier,pay,ref,failure,cancel,cancelledPassengerIndexes);}
  public Booking validated(Instant now){require(Step.VALIDATE);quote.valid(now);return next(status,payment,reservation,refund,Step.AUTHORIZE,supplierReference,paymentReference,refundReference,null,cancellation,now);}
  public Booking authorized(boolean ok,String ref,Instant now){require(Step.AUTHORIZE);return next(ok?status:Status.FAILED,ok?Payment.AUTHORIZED:Payment.DECLINED,reservation,refund,ok?Step.RESERVE:Step.DONE,supplierReference,ref,refundReference,ok?null:"AUTH_DECLINED",cancellation,now);}
  public Booking reserved(boolean ok,Reservation allocated,String ref,Instant now){require(Step.RESERVE);if(payment!=Payment.AUTHORIZED||ok&&allocated!=expectedReservation(quote.selection().availability()))throw new DomainFailure(BOOKING_CONFLICT,"Invalid reservation transition.");return next(status,payment,ok?allocated:Reservation.REJECTED,refund,ok?Step.CAPTURE:Step.VOID,ok?ref:null,paymentReference,refundReference,ok?null:"RESERVATION_REJECTED",cancellation,now);}
  public Booking captured(boolean ok,String ref,Instant now){require(Step.CAPTURE);if(payment!=Payment.AUTHORIZED||!issuedReservation(reservation))throw new DomainFailure(BOOKING_CONFLICT,"Capture requires an authorized payment and allocated supplier reservation.");return next(ok?Status.ISSUED:status,ok?Payment.CAPTURED:Payment.AUTHORIZED,reservation,refund,ok?Step.DONE:Step.CANCEL,supplierReference,ref,refundReference,ok?null:"CAPTURE_DECLINED",cancellation,now);}
  public CancellationQuote cancellationQuote(UUID qid,Instant now){if(status!=Status.ISSUED||step!=Step.DONE||passengerChanges()||!quote.departure().isAfter(now))throw new DomainFailure(BOOKING_CONFLICT,"Only issued tickets before departure can be cancelled.");var amount=quote.selection().availability().base().amount().multiply(BigDecimal.valueOf(quote.selection().passengers().size()));Instant expiry=now.plusSeconds(300).isBefore(quote.departure())?now.plusSeconds(300):quote.departure();return new CancellationQuote(qid,id,quote.owner(),version,Money.inr(amount),Money.inr(quote.selection().total().amount().subtract(amount)),now,expiry,null);}
  public Booking cancel(Cancellation c,Instant now){if(status!=Status.ISSUED||step!=Step.DONE||c.quote().bookingVersion()!=version||!c.quote().expiresAt().isAfter(now)||!quote.departure().isAfter(now))throw new DomainFailure(BOOKING_CONFLICT,"Cancellation quote expired or the booking changed. Review a fresh quote.");if(c.quote().passengerIndexes()!=null)validateSelection(c.quote().passengerIndexes());else if(passengerChanges())throw new DomainFailure(BOOKING_CONFLICT,"Use passenger-aware cancellation for this booking.");return next(Status.CANCELLATION_PENDING,payment,reservation,Refund.NONE,Step.CANCEL,supplierReference,paymentReference,null,null,c,now);}
  public Booking cancelled(Instant now){require(Step.CANCEL);boolean customer=cancellation!=null;boolean due=customer&&cancellation.quote().refundAmount().amount().signum()>0;var indexes=new ArrayList<>(cancelledPassengerIndexes);if(customer)indexes.addAll(cancellationScope());indexes=indexes.stream().distinct().sorted().collect(java.util.stream.Collectors.toCollection(ArrayList::new));boolean all=!customer||indexes.size()==quote.selection().passengers().size();var next=next(customer?(all?Status.CANCELLED:Status.ISSUED):Status.PROCESSING,payment,all?Reservation.CANCELLED:reservation,customer?(due?Refund.PENDING:Refund.NOT_DUE):Refund.NONE,customer?(due?Step.REFUND:Step.DONE):Step.VOID,supplierReference,paymentReference,refundReference,failureCode,cancellation,now);return new Booking(next.id(),next.quote(),next.acceptedAt(),next.scenario(),next.commandId(),next.correlationId(),next.version(),next.createdAt(),next.updatedAt(),next.status(),next.payment(),next.reservation(),next.refund(),next.step(),next.supplierReference(),next.paymentReference(),next.refundReference(),next.failureCode(),next.cancellation(),indexes);}
  public Booking voided(Instant now){require(Step.VOID);return next(Status.FAILED,Payment.VOIDED,reservation,refund,Step.DONE,supplierReference,paymentReference,refundReference,failureCode,cancellation,now);}
  public Booking refundSubmitted(String ref,boolean complete,Instant now){if(step!=Step.REFUND&&step!=Step.REFUND_STATUS)throw new DomainFailure(BOOKING_CONFLICT,"Unexpected refund state.");return next(cancelledPassengerIndexes.size()==quote.selection().passengers().size()?Status.CANCELLED:Status.ISSUED,payment,reservation,complete?Refund.SUCCEEDED:Refund.PENDING,complete?Step.DONE:Step.REFUND_STATUS,supplierReference,paymentReference,ref,failureCode,cancellation,now);}
  public Booking failBeforeEffect(String code,Instant now){if(step==Step.CAPTURE)return captured(false,paymentReference,now);if(step!=Step.VALIDATE&&step!=Step.AUTHORIZE)throw new IllegalStateException("Unknown effect must be reconciled");return next(Status.FAILED,payment,reservation,refund,Step.DONE,supplierReference,paymentReference,refundReference,code,cancellation,now);}
  public Booking resumeFrom(Booking checkpoint,Instant now){if(status!=Status.REVIEW||!id.equals(checkpoint.id())||checkpoint.version()+1!=version||checkpoint.step()==Step.REVIEW||checkpoint.terminal())throw new DomainFailure(BOOKING_CONFLICT,"No valid recovery checkpoint.");return new Booking(id,quote,acceptedAt,scenario,commandId,correlationId,version+1,createdAt,now,checkpoint.status(),checkpoint.payment(),checkpoint.reservation(),checkpoint.refund(),checkpoint.step(),checkpoint.supplierReference(),checkpoint.paymentReference(),checkpoint.refundReference(),checkpoint.failureCode(),checkpoint.cancellation(),cancelledPassengerIndexes);}
  public Booking reconcileLegacy(com.travbook.shared.domain.Recovery.Proof proof,Instant now){if(status!=Status.REVIEW||!proof.bookingId().equals(id)||proof.capturedAmount().compareTo(quote.selection().total().amount())!=0||!proof.paymentReference().equals("MOCK-PAY-"+id)||!proof.supplierReference().equals("MOCK-PNR-"+id))throw new DomainFailure(BOOKING_CONFLICT,"Legacy proof is not bound to this review.");boolean fulfilled=proof.outcome()==com.travbook.shared.domain.Recovery.Outcome.FULFILLED;if(fulfilled!=(cancellation==null)||passengerChanges()||fulfilled&&(proof.committedRefunds().signum()!=0||!proof.reservationState().equals(expectedReservation(quote.selection().availability()).name()))||!fulfilled&&(!proof.reservationState().equals("CANCELLED")||proof.activeUnits()!=0||proof.settledRefunds().compareTo(cancellation.quote().refundAmount().amount())!=0))throw new DomainFailure(BOOKING_CONFLICT,"Legacy outcome is ambiguous.");return new Booking(id,quote,acceptedAt,scenario,commandId,correlationId,version+1,createdAt,now,fulfilled?Status.ISSUED:Status.CANCELLED,Payment.CAPTURED,Reservation.valueOf(proof.reservationState()),Refund.valueOf(proof.refundState()),Step.DONE,proof.supplierReference(),proof.paymentReference(),proof.refundReference(),null,cancellation,fulfilled?cancelledPassengerIndexes:java.util.stream.IntStream.range(0,quote.selection().passengers().size()).boxed().toList());}
  public Booking review(Instant now){return next(Status.REVIEW,payment,reservation,refund,Step.REVIEW,supplierReference,paymentReference,refundReference,"RECONCILIATION_REQUIRED",cancellation,now);}
  public boolean passengerChanges(){return cancellation!=null&&cancellation.quote().passengerIndexes()!=null;}
  public void legacyAllowed(){if(passengerChanges())throw new DomainFailure(BOOKING_CONFLICT,"Use the passenger-aware v2 booking API to view or manage this booking.");}
  public List<Integer> activePassengers(){return java.util.stream.IntStream.range(0,quote.selection().passengers().size()).boxed().filter(i->!cancelledPassengerIndexes.contains(i)).toList();}
  public List<Integer> cancellationScope(){return cancellation==null?List.of():cancellation.quote().passengerIndexes()==null?java.util.stream.IntStream.range(0,quote.selection().passengers().size()).boxed().toList():cancellation.quote().passengerIndexes();}
  private void validateSelection(List<Integer> indexes){if(indexes==null||indexes.isEmpty()||indexes.size()>6||indexes.stream().anyMatch(i->i==null||!activePassengers().contains(i))||new HashSet<>(indexes).size()!=indexes.size())throw new DomainFailure(VALIDATION_FAILED,"Select distinct active passengers.");var remaining=activePassengers().stream().filter(i->!indexes.contains(i)).map(i->quote.selection().passengers().get(i)).toList();if(!remaining.isEmpty())eligible(quote.selection().journey(),quote.selection().availability().travelClass(),quote.selection().availability().quota(),quote.selection().boardingStation(),remaining);}
  public CancellationQuote passengerCancellationQuote(UUID id,List<Integer> indexes,Instant now){if(status!=Status.ISSUED||step!=Step.DONE||!quote.departure().isAfter(now))throw new DomainFailure(BOOKING_CONFLICT,"Finish the current workflow before cancelling active passengers before departure.");validateSelection(indexes);var selected=indexes.stream().sorted().toList();var a=quote.selection().availability();var count=BigDecimal.valueOf(selected.size());var expiry=now.plusSeconds(300).isBefore(quote.departure())?now.plusSeconds(300):quote.departure();return new CancellationQuote(id,this.id,quote.owner(),version,Money.inr(a.base().amount().multiply(count)),Money.inr(a.fees().amount().multiply(count)),now,expiry,selected);}
  public void voucherAllowed(){if(status!=Status.ISSUED||!issuedReservation(reservation)||payment!=Payment.CAPTURED)throw new DomainFailure(BOOKING_CONFLICT,"A summary is available only for a currently issued MOCK rail ticket.");}
 }
 public static Reservation expectedReservation(Availability availability){return switch(availability.status()){case AVAILABLE->Reservation.CONFIRMED;case RAC->Reservation.RAC;case WAITLIST->Reservation.WAITLIST;default->throw new DomainFailure(OFFER_UNAVAILABLE,"Unbookable rail availability.");};}
 public static boolean issuedReservation(Reservation r){return r==Reservation.CONFIRMED||r==Reservation.RAC||r==Reservation.WAITLIST;}
 public record CancellationResult(UUID quoteId,List<Integer> passengerIndexes,Money refundAmount,Refund status,String reference,Instant completedAt){public CancellationResult{passengerIndexes=List.copyOf(passengerIndexes);}}
 public record Voucher(UUID id,UUID bookingId,Instant createdAt,String sha256,int byteLength,String content,int revision){public Voucher(UUID id,UUID bookingId,Instant createdAt,String sha256,int byteLength,String content){this(id,bookingId,createdAt,sha256,byteLength,content,0);}}
}
